-- The cloud as a factory module (#780, slice 1 of the cloud and the bamboo forest): deck/modules/cloud/src/lib.rs becomes the
-- catalog document `module:cloud` marked `factory: true`, as the small audio modules did in 2026-11-21-factory-audio-modules:
-- read-only, a member derives a module of their own from it. Source only: `files` is the repository's file byte for byte
-- (server tests/Unit/Domain/FactoryModulesTest keeps them equal).
-- The wasm: NOT in this file. It reads as not compiled (no descriptor / wasm, so it is no kind in GET /api/kinds yet) until an
-- admin presses Compile on it in the creator's Sound workspace (POST /api/modules/compile { factory: "cloud" }). ORDER: the build
-- service must carry this deploy's SDK first (the instance table: `#[port(output, instances)]`, `deck_module::Instance`) – with
-- an older SDK it does not build.
-- Stored data: nothing else changes.
-- What it touches:
--   catalog_modules: one row, INSERT IGNORE – an existing row `cloud` (a module a creator made under the name) is left as it is,
--     and then `cloud` is not a factory module (the dry run below shows it; tell the owner).
--   entity_versions: the factory content as the published version of `module:cloud` (message = the marker below); a published
--     version of that key from before becomes a draft (history).
-- Dry run (before): SELECT id, JSON_EXTRACT(data, '$.factory') AS factory FROM catalog_modules WHERE id = 'cloud';
--   -> expected: no rows. SELECT entity_key, status, COUNT(*) FROM entity_versions WHERE entity_key = 'module:cloud' GROUP BY entity_key, status;
--   -> expected: no rows (else: published versions that become history).
-- Test (after): SELECT id, JSON_EXTRACT(data, '$.factory'), JSON_LENGTH(data, '$.files') FROM catalog_modules WHERE id = 'cloud';
--   -> one row, true 1; SELECT entity_key FROM entity_versions WHERE status = 'published' AND message = 'factory module (migration 2026-11-22-factory-cloud)';
--   -> one row.
-- Plan's row counts on a database without it: 1 . 0 . 1. MariaDB 10.11, idempotent: a second run changes nothing (INSERT IGNORE;
-- the published marker version exists). Escaping: plain string literals (no NO_BACKSLASH_ESCAPES): `\\` is one backslash of the
-- JSON, `\'` a quote; the row is one line.

INSERT IGNORE INTO `catalog_modules` (`id`, `position`, `data`, `updated_at`, `updated_by`) VALUES
  ('cloud', 13, '{"id":"cloud","name":"cloud","factory":true,"files":{"lib.rs":"//! `cloud` – a low-poly cloud floating above its place: a lumpy cluster of puffs (the core\'s placeholder shape until the\\n//! owner\'s models come) that drifts with the wind, breathes a little and wraps back when it has drifted past its\\n//! range. Its layout is the node\'s `seed`; every step rewrites its instance table, so the table is the same on every deck.\\n//!\\n//! Build: `cargo build --release --target wasm32-unknown-unknown -p cloud-module`.\\n#![allow(clippy::duplicated_attributes)]\\nuse deck_module::instances::shape;\\nuse deck_module::{math, Ctx, Instance, Module, Outputs};\\n\\n/// the most puffs (the table\'s capacity)\\npub const MOST: usize = 24;\\n\\n#[derive(Module)]\\n#[module(name = \\"cloud\\", domain = \\"control\\", doc = \\"a low-poly cloud of puffs floating above its place, drifting with the wind\\")]\\n#[port(output, instances, name = \\"shapes\\", capacity = 24, doc = \\"the puffs, drawn at the node\'s place\\")]\\n#[preset(name = \\"storm\\", doc = \\"a dark, wide cloud in a strong wind\\", values(puffs = 18.0, size = 6.0, drift = 2.5, light = 35.0))]\\npub struct Cloud {\\n    #[param(range = 3.0..24.0, default = 9.0, doc = \\"how many puffs\\")]\\n    puffs: f32,\\n    #[param(range = 0.5..20.0, default = 3.0, unit = \\"m\\", doc = \\"how wide the cloud is\\")]\\n    size: f32,\\n    #[param(range = -5.0..5.0, default = 0.4, doc = \\"the wind: metres a second along the stage\'s x\\")]\\n    drift: f32,\\n    #[param(range = 0.0..50.0, default = 4.0, unit = \\"m\\", doc = \\"how high above its place it floats\\")]\\n    height: f32,\\n    #[param(range = 2.0..200.0, default = 16.0, unit = \\"m\\", doc = \\"how far it drifts before it wraps back\\")]\\n    range: f32,\\n    #[param(range = 0.0..1.0, default = 0.6, doc = \\"its colour\'s hue\\")]\\n    hue: f32,\\n    #[param(range = 0.0..100.0, default = 6.0, unit = \\"%\\", doc = \\"how much colour\\")]\\n    tint: f32,\\n    #[param(range = 0.0..100.0, default = 92.0, unit = \\"%\\", doc = \\"how bright\\")]\\n    light: f32,\\n    /// metres drifted, inside the range\\n    drifted: f64,\\n    /// seconds since the start (the breathing)\\n    time: f64,\\n}\\n\\n/// a number in [0, 1) from the seed and two indices – the same on every platform\\nfn unit(seed: u64, i: u64, k: u64) -> f32 {\\n    let mut z = seed ^ i.wrapping_mul(0x9e37_79b9_7f4a_7c15) ^ k.wrapping_mul(0xc2b2_ae3d_27d4_eb4f);\\n    z = (z ^ (z >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);\\n    z = (z ^ (z >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);\\n    z ^= z >> 31;\\n    (z >> 40) as f32 / (1u64 << 24) as f32\\n}\\n\\n/// hue, saturation, value (0 … 1) → linear RGB\\nfn hsv(h: f32, s: f32, v: f32) -> [f32; 3] {\\n    let k = |n: f32| {\\n        let k = math::fmod(n + h * 6.0, 6.0);\\n        v - v * s * k.min(4.0 - k).clamp(0.0, 1.0)\\n    };\\n    [k(5.0), k(3.0), k(1.0)].map(|c| math::pow(c, 2.2))\\n}\\n\\nimpl Module for Cloud {\\n    fn control(&mut self, ctx: &Ctx, out: &mut Outputs) {\\n        let dt = ctx.frames() as f64 / ctx.rate().max(1.0);\\n        self.time += dt;\\n        let range = f64::from(self.range.max(2.0));\\n        self.drifted = math::libm::fmod(self.drifted + f64::from(self.drift) * dt, range);\\n        if self.drifted < 0.0 {\\n            self.drifted += range;\\n        }\\n        // the cluster\'s middle runs from one end of the range to the other\\n        let x = (self.drifted - range * 0.5) as f32;\\n        let n = (math::round(self.puffs) as usize).clamp(3, MOST);\\n        let size = self.size.max(0.1);\\n        let seed = ctx.seed();\\n        let base = hsv(self.hue, self.tint * 0.01, self.light * 0.01);\\n        let t = self.time as f32;\\n        let mut table = out.instances();\\n        table.clear();\\n        for i in 0..n as u64 {\\n            let r = |k: u64| unit(seed, i, k);\\n            // across the cloud, a flat bottom and a heaped middle\\n            let across = r(0) - 0.5;\\n            let middle = 1.0 - 2.0 * across.abs();\\n            let at = [x + across * size, self.height + r(1) * size * 0.3 * (0.4 + 0.6 * middle), (r(2) - 0.5) * size * 0.45];\\n            let breath = 1.0 + 0.05 * math::sin(core::f32::consts::TAU * (t * 0.11 + r(3)));\\n            let radius = size * (0.16 + 0.14 * r(4)) * (0.6 + 0.4 * middle) * breath;\\n            let bob = 0.03 * size * math::sin(core::f32::consts::TAU * (t * 0.07 + r(5)));\\n            let yaw = core::f32::consts::TAU * r(6) + 0.05 * t;\\n            let turn = [0.0, math::sin(yaw * 0.5), 0.0, math::cos(yaw * 0.5)];\\n            // the underside a little darker\\n            let shade = 0.82 + 0.18 * r(1);\\n            table.push(\\n                Instance::new(shape::PUFF, [at[0], at[1] + bob, at[2]])\\n                    .turned(turn)\\n                    .scaled([radius * 1.25, radius * 0.85, radius])\\n                    .coloured([base[0] * shade, base[1] * shade, base[2] * shade, 1.0]),\\n            );\\n        }\\n    }\\n}\\n"}}', UTC_TIMESTAMP(), 'migration:2026-11-22-factory-cloud');

-- an earlier published version of the key becomes history (only where the factory row is ours)
UPDATE `entity_versions` SET `status` = 'draft'
 WHERE `entity_key` = 'module:cloud' AND `status` = 'published'
   AND COALESCE(`message`, '') <> 'factory module (migration 2026-11-22-factory-cloud)'
   AND EXISTS (SELECT 1 FROM `catalog_modules` m WHERE CONCAT('module:', m.`id`) COLLATE utf8mb4_general_ci = `entity_versions`.`entity_key`
               AND JSON_CONTAINS(m.`data`, 'true', '$.factory'));

-- the factory content as the published version (the creator's document)
INSERT INTO `entity_versions` (`entity_key`, `kind`, `toon`, `locale`, `json`, `author`, `created_at`, `status`, `message`)
SELECT CONCAT('module:', m.`id`), 'module', NULL, NULL, m.`data`, NULL, UTC_TIMESTAMP(), 'published', 'factory module (migration 2026-11-22-factory-cloud)'
  FROM `catalog_modules` m
 WHERE m.`id` = 'cloud' AND JSON_CONTAINS(m.`data`, 'true', '$.factory')
   AND NOT EXISTS (SELECT 1 FROM `entity_versions` e WHERE e.`entity_key` = CONCAT('module:', m.`id`) COLLATE utf8mb4_general_ci
                   AND e.`message` = 'factory module (migration 2026-11-22-factory-cloud)');
